int tui_init(void) {
	initscr();
	if (LINES < 24 || COLS < 72) {
		endwin();
		return FALSE;
	}
	cbreak();
	noecho();
	wquad = newwin(PANELH, QUADW, 0, 0);
	wstat = newwin(PANELH, COLS-QUADW, 0, QUADW);
	wmsg = newwin(LINES-PANELH, COLS-2, PANELH, 1);
